const totalDistribue=resultats.filter(r=>!r.exclu).reduce((sum,r)=>sum+r.montant,0);const radd=!awl&&partsAsaba.filter(p=>!p.exclu).length===0&&totalDistribue<totalSuccession;if(radd){avertissements.push('Cas de Radd (رد) : le surplus est redistribué aux héritiers à parts fixes proportionnellement.');}// Vérifier s'il n'y a aucun héritier
if(resultats.filter(r=>!r.exclu).length===0){avertissements.push('Aucun héritier trouvé. La succession revient au Trésor public (بيت المال).');}return{totalSuccession,devises:devise,madhab,aslMasala:asl,awl,radd,heritiers:resultats,totalDistribue,resume:genererResume(resultats,totalSuccession,devise),resumeAr:genererResumeArabe(resultats),avertissements};}function genererResume(resultats,total,devise){const heritiers=resultats.filter(r=>!r.exclu&&r.montant>0);if(heritiers.length===0)return'Aucun héritier qualifié trouvé.';const lignes=heritiers.map(h=>{const info=require('./heritiers').HERITIERS_INFO[h.type];return`${info.nomFr} (×${h.nombre}) : ${h.fraction} = ${h.montant.toLocaleString()} ${devise}`;});return`Répartition de ${total.toLocaleString()} ${devise} :\n${lignes.join('\n')}`;}function genererResumeArabe(resultats){const heritiers=resultats.filter(r=>!r.exclu&&r.montant>0);if(heritiers.length===0)return'لا يوجد وارث';const lignes=heritiers.map(h=>{const info=require('./heritiers').HERITIERS_INFO[h.type];return`${info.nomAr}: ${h.fraction}`;});return lignes.join(' | ');}

